// PostgREST devolve o jsonb da função direto no corpo — a função é escalar
// (RETURNS jsonb), não SETOF, então não vem embrulhado em array. O fallback
// `.payload` cobre o caso de alguém voltar pro node Postgres depois.
const body = $input.first().json;
let raw = (body && body.payload !== undefined) ? body.payload : body;
if (typeof raw === 'string') raw = JSON.parse(raw);
// Defensivo: dependendo da versão, o n8n pode entregar o array de resultado do
// PostgREST cru em vez de dividir em itens. Sem isso a mensagem sairia com
// "undefined" em todo número, em silêncio — pior que quebrar.
if (Array.isArray(raw)) raw = raw[0];
const r = raw;

if (!r || r.periodo_inicio === undefined) {
  throw new Error('Payload inesperado do RPC: ' + JSON.stringify(body).slice(0, 300));
}

// Nenhuma conta e NENHUMA data é feita aqui: relatorio_semanal_esteira() já
// devolveu tudo agregado e já devolveu a semana em America/Sao_Paulo. O n8n roda
// no timezone do container, então recalcular data neste node é a forma mais
// fácil de o relatório sair com a semana errada.
const br = (iso) => String(iso).slice(0, 10).split('-').reverse().join('/'); // 24/08/2026
const dm = (iso) => br(iso).slice(0, 5);                                    // 24/08

const L = [];
L.push('*Relatório Semanal — Focus FinTax*');
L.push(`${dm(r.periodo_inicio)} a ${br(r.periodo_fim)}`);
L.push('');
L.push(`Leads em tratamento na semana: *${r.leads_semana}*`);
L.push(`Clientes que mudaram de etapa: *${r.movimentacao_esteira_semana}*`);
L.push('');

L.push(`*Leads em andamento (${r.leads_em_andamento})*`);
if (r.leads_por_etapa.length) {
  for (const e of r.leads_por_etapa) L.push(`• ${e.etapa}: ${e.total}`);
} else {
  L.push('• nenhum lead aberto no funil');
}
L.push('');

// Etapas zeradas saem da lista — numa esteira de 7 etapas com 3 clientes, a
// mensagem viraria mais zero que informação.
const etapasComCliente = (r.esteira_por_etapa || []).filter((e) => e.total > 0);
L.push(`*Esteira administrativa (${r.esteira_total})*`);
if (etapasComCliente.length) {
  for (const e of etapasComCliente) {
    const atraso = e.atrasados
      ? ` (${e.atrasados} atrasado${e.atrasados > 1 ? 's' : ''})`
      : '';
    L.push(`• ${e.etapa}: ${e.total}${atraso}`);
  }
} else {
  L.push('• nenhum cliente ativo na esteira');
}
L.push('');

if (r.parados_total) {
  L.push(`*Parados (${r.parados_total})*`);
  for (const m of r.parados) {
    L.push(`• ${m.motivo}: ${m.total} — pior caso ${m.pior_atraso_dias}d além do prazo`);
  }
} else {
  L.push('*Parados:* ninguém além do SLA nesta semana.');
}
L.push('');
L.push('Painel: https://focusfintax.com/esteira');

return [{
  json: {
    mensagem: L.join('\n'),
    periodo_inicio: r.periodo_inicio,
    periodo_fim: r.periodo_fim,
  },
}];
